update public.learning_paths
set
  title = 'Demand Planning and Forecasting',
  goal = 'Demand Planning and Forecasting',
  summary = 'This guide connects forecasting methods to S&OP, inventory, safety stock, capacity, MPS, MRP, ERP, revenue management, resilience, scenario planning, control towers, and AI-enabled forecasting. The content provides an end-to-end supply-chain planning and decision framework.',
  data = $dpfjson${"slug": "demand-planning-and-forecasting", "title": "Demand Planning and Forecasting", "description": "This guide connects forecasting methods to S&OP, inventory, safety stock, capacity, MPS, MRP, ERP, revenue management, resilience, scenario planning, control towers, and AI-enabled forecasting. The content provides an end-to-end supply-chain planning and decision framework.", "topics": [{"id": "6b80e02c-e099-4dea-9afc-81da3c1c3fdf", "type": "topic", "title": "Demand Planning as a Supply Chain Decision System", "description": "Frame demand planning as the process that links market signals, statistical forecasts, inventory, capacity, finance, and executive decisions.", "children": [{"id": "6c15aed4-625f-4d5d-8b80-2ac6e3c73ff2", "type": "subtopic", "title": "Purpose of Demand Planning", "children": [{"id": "70ef8d00-3029-470e-bbf6-931c073cb219", "type": "concept", "title": "Demand plan, statistical forecast, consensus forecast, shipment forecast, sell-through, orders, and consumption"}, {"id": "fc400bad-a2e2-4cd0-8fd4-9a1c81b94f13", "type": "concept", "title": "Planning horizons: operational, tactical, and strategic"}, {"id": "ba0407dc-cfe5-45e7-862a-5811a1c93092", "type": "concept", "title": "Links to inventory, service level, capacity, procurement, logistics, and financial planning"}], "description": "Demand planning turns uncertain customer demand into coordinated decisions across supply chain, operations, commercial teams, and finance."}, {"id": "6f60b2dc-3f79-4746-b27d-067cb69f9911", "type": "subtopic", "title": "Planning Roles and Operating Model", "children": [{"id": "bfb0a3ea-fbaf-49f9-ae48-92f1be988ac6", "type": "concept", "title": "Demand planner, supply planner, category manager, sales account lead, finance partner, and S&OP owner"}, {"id": "935f11e1-6540-4cc7-823e-4dbca9c84843", "type": "concept", "title": "Planning calendar, forecast cycle, handoffs, approvals, and escalation"}, {"id": "f50539d2-228b-4719-aa6d-ea8152fd12c3", "type": "concept", "title": "RACI, decision rights, and accountability"}], "description": "Students learn how planners work with sales, marketing, operations, finance, suppliers, and executives."}, {"id": "f563fa9b-7274-4310-88db-af2f412a7839", "type": "subtopic", "title": "Forecast Value and Business Impact", "children": [{"id": "b8a62acc-cc60-4cfa-a5c4-3cbbfd2deb90", "type": "concept", "title": "Service, cost, inventory, margin, cash, capacity, and customer experience"}, {"id": "1cc5be5b-ed97-4893-bdbe-9c964f196ef0", "type": "concept", "title": "Forecast value added, baseline benchmark, and planning effectiveness"}, {"id": "861e726b-e758-469c-a876-2205f56b382d", "type": "concept", "title": "Avoiding model-first thinking when process or incentives are the real issue"}], "description": "A forecast is useful only if it improves decisions and tradeoffs."}]}, {"id": "f1efee2d-a5ee-465b-b656-f7423c7c58fe", "type": "topic", "title": "Demand Patterns, Data Structures, and Forecasting Problem Definition", "description": "Learn how demand behaves across products, customers, channels, geographies, and time horizons before selecting models.", "children": [{"id": "8d1b23cc-5022-4689-9718-2857bb64640c", "type": "subtopic", "title": "Demand Pattern Recognition", "children": [{"id": "abb9dbe6-fd8a-4b97-b257-ddf82aa5aa7f", "type": "concept", "title": "Level, trend, seasonality, cycles, volatility, intermittent demand, slow movers, and launch curves"}, {"id": "7c97a5e6-e6ac-4dd3-9817-8e8d2c84a0a1", "type": "concept", "title": "Stable, erratic, lumpy, obsolete, and new-product demand"}, {"id": "1f0de331-682b-4966-9ade-c8d8dd1f050d", "type": "concept", "title": "Visual diagnostics before modeling"}], "description": "Pattern recognition helps planners choose methods and avoid applying one model to every SKU."}, {"id": "a142aff4-e63e-403e-968d-6ac19ec1468a", "type": "subtopic", "title": "Planning Hierarchies and Granularity", "children": [{"id": "de656a93-37c3-4915-9520-a683d1a41176", "type": "concept", "title": "SKU, SKU-location, product family, brand, category, customer, region, channel, and time bucket"}, {"id": "b31a75b9-e9ff-4b36-80e1-5c798ba2f673", "type": "concept", "title": "Daily, weekly, monthly, and rolling horizons"}, {"id": "1ef05fe9-a32e-41db-bd6a-ba99eedfce95", "type": "concept", "title": "Top-down, bottom-up, and middle-out planning"}], "description": "Forecasts must be built at the level where decisions are made and reconciled across the organization."}, {"id": "bbd5b19f-f5d0-4765-be93-dd2e8e470627", "type": "subtopic", "title": "Problem Definition and Forecast Objective", "children": [{"id": "40de7660-2fc0-4dbc-b661-7bc281089a7c", "type": "concept", "title": "Target variable, forecast horizon, lead time, latency, data availability, and refresh cadence"}, {"id": "d897a200-e898-40ae-a3d9-4c2624b167c8", "type": "concept", "title": "Point forecasts, intervals, scenarios, and event-based forecasts"}, {"id": "115e7b3f-5505-4cdf-a092-1e7a0991ef32", "type": "concept", "title": "Decision rules for when accuracy is good enough"}], "description": "Good forecasting starts by defining the decision, target, horizon, and tolerance for error."}]}, {"id": "ce657d7d-5f10-438e-997e-d882f5eac117", "type": "topic", "title": "Forecasting Workflow, Data Preparation, and Baseline Models", "description": "Build a disciplined forecasting pipeline from data extraction and cleaning through naive benchmarks and reproducible outputs.", "children": [{"id": "2908c5a4-b47e-47d1-bb6d-9cf912437f7a", "type": "subtopic", "title": "Data Pipeline and Cleaning", "children": [{"id": "4a307acb-6f24-4c1c-854a-d00abf684560", "type": "concept", "title": "Extract, transform, load, data dictionary, missing values, duplicates, returns, cancellations, stockouts, and substitutions"}, {"id": "92855829-c798-4c45-af18-5f30af217a68", "type": "concept", "title": "Outlier review, promotion flags, product lifecycle flags, and master data quality"}, {"id": "a40d44ec-155d-459a-8fc5-cd2ae319bec1", "type": "concept", "title": "Version control and reproducible forecast runs"}], "description": "Forecasting quality depends heavily on clean, well-defined, and auditable demand data."}, {"id": "49ab8bd8-bd55-4d3c-9ad9-454a0f5f6f74", "type": "subtopic", "title": "Baseline Forecasts", "children": [{"id": "6d2e6a2e-3d69-43db-a859-b0317e8779c8", "type": "concept", "title": "Naive, seasonal naive, moving average, drift, simple average, and last-year-same-period"}, {"id": "9cef3272-a697-4311-b0fb-c2c30d55fafe", "type": "concept", "title": "Benchmarking and forecast value added"}, {"id": "29dd023f-5b1d-443f-823f-d4af94323df5", "type": "concept", "title": "When simple models outperform complex ones"}], "description": "Baseline models create a fair reference point before adding complexity."}, {"id": "5ac09532-ec71-4d53-b081-2f6723854c8a", "type": "subtopic", "title": "Workflow Discipline", "children": [{"id": "bd60c913-cc57-4965-b662-fc6b0978d415", "type": "concept", "title": "Model selection, training windows, holdout periods, documentation, approval workflow, and archive"}, {"id": "7eb2d6a9-bdb0-493e-9c9f-8c5b0e29d1fe", "type": "concept", "title": "Forecast snapshot, assumptions log, and exception notes"}, {"id": "cadad2be-f006-4aa1-8da2-afc014a88389", "type": "concept", "title": "Cycle cadence and handoff to downstream planning"}], "description": "A robust process makes forecasts repeatable and explainable."}]}, {"id": "2696a51d-f10d-4e0f-8b4a-2104b3a66379", "type": "topic", "title": "Moving Averages, Exponential Smoothing, and Classical Time-Series Methods", "description": "Use core time-series methods to forecast level, trend, seasonality, and noise in operational demand data.", "children": [{"id": "7def7881-18ab-42bf-9b30-4258e258bd65", "type": "subtopic", "title": "Moving Average Methods", "children": [{"id": "22635134-f390-45e6-8aa6-babb558ad5f9", "type": "concept", "title": "Simple moving average, weighted moving average, window length, smoothing versus responsiveness"}, {"id": "1c02be76-368f-4bed-adf0-b1d7c4d07c8d", "type": "concept", "title": "Lag, noise reduction, and sensitivity to outliers"}, {"id": "d4668174-e090-487c-9347-5f4fbe7d88c0", "type": "concept", "title": "Use cases and limitations"}], "description": "Moving averages smooth random variation and provide intuitive forecasts for stable demand."}, {"id": "d9639be3-8c8e-43b4-9d29-540e192406d5", "type": "subtopic", "title": "Exponential Smoothing", "children": [{"id": "29a902b7-43e8-4039-8681-ff08d82c5018", "type": "concept", "title": "Simple exponential smoothing, Holt trend, Holt-Winters, damped trend, and smoothing parameters"}, {"id": "15324c5a-ba56-43af-8d69-f58eb2132dd3", "type": "concept", "title": "Level, trend, seasonality, and automatic model selection"}, {"id": "554172f9-a675-4a20-af60-f6ee6d9ec60a", "type": "concept", "title": "Interpreting fitted values and residuals"}], "description": "Exponential smoothing methods are workhorses for operational forecasting."}, {"id": "b8aa5516-afd9-4d00-ab4c-7036f92da175", "type": "subtopic", "title": "ARIMA and Classical Time Series", "children": [{"id": "3aef488e-824c-4f8e-aba7-9cdb63a554ef", "type": "concept", "title": "Stationarity, differencing, autocorrelation, ACF, PACF, AR, MA, ARIMA, and SARIMA"}, {"id": "59d142f5-0e57-4b24-978b-068ca568ab8c", "type": "concept", "title": "Residual diagnostics and model adequacy"}, {"id": "ca548a60-07b2-4405-a4c9-f06ac222b225", "type": "concept", "title": "When classical statistical methods remain valuable"}], "description": "ARIMA-style methods deepen students' understanding of autocorrelation and temporal structure."}]}, {"id": "912e3605-d826-434c-a697-ffc67e4421e4", "type": "topic", "title": "Regression, Causal Drivers, and Demand Sensing", "description": "Incorporate price, promotions, events, weather, economic indicators, and digital signals into demand forecasts.", "children": [{"id": "7df74369-0d10-47fe-b8b8-33dc07a24176", "type": "subtopic", "title": "Causal Forecasting with Regression", "children": [{"id": "d94b2102-6a4a-4acb-8936-bf18ee069ab4", "type": "concept", "title": "Linear regression, dummy variables, lagged variables, interactions, and elasticities"}, {"id": "6ad34c4a-f02e-4b01-bf0b-65bb57da20a8", "type": "concept", "title": "Price, promotion, distribution, advertising, weather, holidays, and macro indicators"}, {"id": "81127918-a184-482c-80c3-1a2666e44726", "type": "concept", "title": "Multicollinearity, omitted variables, and overfitting"}], "description": "Regression lets planners include drivers that explain changes in demand rather than only extrapolating history."}, {"id": "47c4601c-ff02-43dd-a223-f5480111fd93", "type": "subtopic", "title": "Demand Sensing Signals", "children": [{"id": "b80affb4-0122-4f47-8a1f-0af2e26fa333", "type": "concept", "title": "POS, orders, search trends, web traffic, social signals, syndicated data, retailer data, and IoT signals"}, {"id": "67251172-ed21-4d87-967b-07ffd6b81b7e", "type": "concept", "title": "Latency, signal quality, and short-horizon adjustment"}, {"id": "cdd719d4-bb59-48f3-99bf-7e2380eb2fe4", "type": "concept", "title": "Separating noise from meaningful demand shifts"}], "description": "Demand sensing uses near-real-time signals to update short-term forecasts."}, {"id": "c6d1c46f-da2c-47de-a3d0-1c13e0ae98b1", "type": "subtopic", "title": "Commercial Assumptions and Forecast Overrides", "children": [{"id": "964b4bcc-cd2d-4701-b92a-0acfa203b9a0", "type": "concept", "title": "Promotions, launches, delistings, price changes, customer wins/losses, and distribution changes"}, {"id": "e52dbc5f-6f6c-4b87-b0c1-1638b61995d9", "type": "concept", "title": "Override reason codes and forecast value added"}, {"id": "42572750-533c-416d-b314-e15c4fb13366", "type": "concept", "title": "Preventing optimism bias and sandbagging"}], "description": "Business knowledge can improve forecasts when overrides are governed and evaluated."}]}, {"id": "50ecf30b-1abe-4d5c-9ce8-c80a38c49a27", "type": "topic", "title": "Seasonality, Calendars, Promotions, and Intermittent Demand", "description": "Handle recurring patterns, holiday effects, promotion lifts, new item uncertainty, and sparse or lumpy demand.", "children": [{"id": "e48f32ed-a546-4ba3-8478-2a86da56bd80", "type": "subtopic", "title": "Seasonality and Calendar Effects", "children": [{"id": "8604deaf-59f5-4e25-8078-fe34b59858de", "type": "concept", "title": "Weekly, monthly, quarterly, annual, holiday, fiscal calendar, and trading-day effects"}, {"id": "f0cac83c-2f6e-450b-b0f4-506a78ba492c", "type": "concept", "title": "Seasonal indexes, decomposition, SARIMA, and seasonal exponential smoothing"}, {"id": "4a39ded6-82c0-4ca4-a623-a562000dbb23", "type": "concept", "title": "Calendar alignment and moving holidays"}], "description": "Seasonality must be modeled carefully because many supply chain decisions depend on timing."}, {"id": "6fb5ef36-29cb-4d4d-ae32-429ff406aa2c", "type": "subtopic", "title": "Promotional and Event Demand", "children": [{"id": "b1cfaae2-b09a-42e2-a087-daa2ec979e96", "type": "concept", "title": "Promotion lift, pre-buy, post-promotion dip, cannibalization, halo effects, and event flags"}, {"id": "146f1776-a1b0-4f20-829f-5f53f81025cd", "type": "concept", "title": "Baseline versus incremental demand"}, {"id": "4f7c9b34-4815-49de-ae41-055e8f6e35db", "type": "concept", "title": "Promotion planning with sales and marketing"}], "description": "Promotions can distort history and create recurring demand spikes."}, {"id": "b755feb2-3473-421c-b397-2880bba7b76f", "type": "subtopic", "title": "Intermittent and Sparse Demand", "children": [{"id": "b3748a7c-d2a1-482a-8127-31cbc91c798a", "type": "concept", "title": "Intermittent, lumpy, slow-moving, spare parts, and long-tail SKUs"}, {"id": "6268f26a-efd6-498a-a985-f53b1f7869c0", "type": "concept", "title": "Croston methods, service parts, aggregation, and stocking policy"}, {"id": "529a9a56-9420-4f11-852f-094b29fd14e2", "type": "concept", "title": "Obsolescence, lifecycle, and minimum order quantities"}], "description": "Slow-moving items need special treatment because ordinary error metrics and methods can mislead."}]}, {"id": "eb871501-ed59-4b02-ae49-63ca1c15d5b1", "type": "topic", "title": "Forecast Accuracy, Bias, Uncertainty, and Exception Management", "description": "Evaluate forecasts with the right metrics, diagnose bias, quantify uncertainty, and manage exceptions systematically.", "children": [{"id": "f87c143f-e81c-4c7f-9394-61e2bf913a89", "type": "subtopic", "title": "Forecast Error Metrics", "children": [{"id": "644ec8b5-c28d-4158-b9a5-e3c3ba9d5360", "type": "concept", "title": "MAE, MAPE, WAPE, RMSE, MASE, bias, tracking signal, and service-weighted accuracy"}, {"id": "2d4c2618-914e-4186-8165-f154e26a3950", "type": "concept", "title": "Scale dependence, zero demand, low-volume distortion, and aggregation effects"}, {"id": "997e211f-eb69-4d55-a6fb-6488d78f881d", "type": "concept", "title": "Metric selection by SKU class and decision need"}], "description": "Metrics should match the decision context rather than reward misleading precision."}, {"id": "ce080698-0823-43fc-aa78-fe5f4a63b54c", "type": "subtopic", "title": "Bias and Uncertainty", "children": [{"id": "19b43935-796d-4242-94a5-2934e384f806", "type": "concept", "title": "Positive and negative bias, optimism bias, forecast intervals, prediction intervals, and confidence bands"}, {"id": "a4631d88-5023-4ca6-980b-cd1f15c91bab", "type": "concept", "title": "Error distributions, scenario ranges, and risk buffers"}, {"id": "e14fc709-f2b7-4ae2-b71a-116c768bb0e2", "type": "concept", "title": "Communicating uncertainty to executives"}], "description": "Planning requires understanding not only average error but also systematic bias and forecast range."}, {"id": "9a5c46d5-fbc9-4ecd-a815-fbf6778ad57c", "type": "subtopic", "title": "Exception Management", "children": [{"id": "22c6dd58-4711-414c-a43c-2e4c33d094de", "type": "concept", "title": "Thresholds, alerts, outliers, high-value SKUs, high-error SKUs, and planner workbenches"}, {"id": "6477d287-9283-4e71-aaa6-8b51de07756b", "type": "concept", "title": "Root-cause coding and action tracking"}, {"id": "bcb96f72-614a-4473-8fd1-060fb4b81aa4", "type": "concept", "title": "Automate the routine, review the material"}], "description": "Exception management focuses planner attention where human review adds the most value."}]}, {"id": "05eb308f-cf2f-4157-8f32-1c7d43822dbc", "type": "topic", "title": "Hierarchical, Multivariate, and Machine Learning Forecasting", "description": "Extend forecasting across product hierarchies, locations, channels, and advanced model families while preserving business interpretability.", "children": [{"id": "7190b2aa-b8ab-4bbb-99f8-16ccbf7760bb", "type": "subtopic", "title": "Hierarchical Forecasting", "children": [{"id": "ca9399a0-edab-4147-b725-6b89a83191cb", "type": "concept", "title": "Top-down, bottom-up, middle-out, reconciliation, coherence, and aggregation constraints"}, {"id": "b98a9f84-6b5c-4a19-a0c3-68bcec1497fe", "type": "concept", "title": "Product family, SKU-location, customer, region, and channel hierarchies"}, {"id": "d4eba934-1444-4d6d-a44f-e9162d990ac1", "type": "concept", "title": "Accuracy and accountability across levels"}], "description": "Hierarchical forecasting reconciles forecasts across product, customer, geography, and channel levels."}, {"id": "2ac08054-0e5d-4176-878b-6caa80a0ef26", "type": "subtopic", "title": "Multivariate and External-Signal Models", "children": [{"id": "a7031453-8b1d-477a-8979-4763aabb1548", "type": "concept", "title": "Vector autoregression, dynamic regression, transfer functions, leading indicators, and causal features"}, {"id": "5165bc7e-561b-461f-9fa0-1b45151c35a2", "type": "concept", "title": "Cross-item effects, substitution, cannibalization, and shared seasonality"}, {"id": "0bab69d1-9b33-4c9d-bc88-85bbcf44cae7", "type": "concept", "title": "Model interpretability and business review"}], "description": "Multivariate models allow demand to be modeled alongside related variables."}, {"id": "75d4d784-8793-4024-9821-7268ddbc151f", "type": "subtopic", "title": "Machine Learning for Forecasting", "children": [{"id": "1538d779-cbf9-4038-ab6a-90915a74d64a", "type": "concept", "title": "Random forests, gradient boosting, neural networks, recurrent models, Prophet-style decompositions, and ensemble models"}, {"id": "c9b7d2e8-d437-487b-b68b-5a235f509abd", "type": "concept", "title": "Feature engineering, rolling validation, leakage, and overfitting"}, {"id": "68ac020f-ff30-4bbf-9e1a-28da263e1b5d", "type": "concept", "title": "Model governance and explainability"}], "description": "Machine learning can improve forecasts, but only when data, validation, and deployment are handled carefully."}]}, {"id": "693849e8-f569-46c5-8cc5-a3911f4a21c3", "type": "topic", "title": "Collaborative Planning, Consensus Forecasting, and S&OP", "description": "Connect statistical forecasts with sales, marketing, supply, operations, finance, and executive decision forums.", "children": [{"id": "4ab7edfd-574b-4146-9e29-91fc8e7db22e", "type": "subtopic", "title": "Collaborative Planning", "children": [{"id": "e77c03fb-1e23-4761-837b-01b6e29d8118", "type": "concept", "title": "CPFR, customer collaboration, supplier collaboration, retailer data, and joint business planning"}, {"id": "7773c11e-e3c0-4105-9f8c-b1667cf286d7", "type": "concept", "title": "Information sharing, trust, cadence, and confidentiality"}, {"id": "a1898b11-e341-4545-82fa-4f1a2f1424a1", "type": "concept", "title": "Using collaboration to reduce uncertainty"}], "description": "Collaborative planning brings demand information from customers, sales, marketing, operations, and suppliers into one process."}, {"id": "759b9f75-0c29-413b-bbc5-6d9d301547c0", "type": "subtopic", "title": "Consensus Forecasting", "children": [{"id": "0010cb6d-bc9d-403d-ae8c-17cda86b6926", "type": "concept", "title": "Demand review, sales input, marketing plans, finance assumptions, and supply constraints"}, {"id": "6b027795-ab13-4363-8513-395ca096c2fe", "type": "concept", "title": "One-number forecast versus scenario ranges"}, {"id": "5a59413a-81fa-4262-9db5-012253573f5e", "type": "concept", "title": "Bias control, documentation, and accountability"}], "description": "Consensus forecasting reconciles statistical evidence with commercial knowledge and operational constraints."}, {"id": "533f3555-67e7-4913-985b-b1f1407cc41a", "type": "subtopic", "title": "S&OP and IBP", "children": [{"id": "d55f6650-b95f-4b8a-82f3-6639863169cf", "type": "concept", "title": "Demand review, supply review, pre-S&OP, executive S&OP, and integrated business planning"}, {"id": "c87fa1ca-9200-4ab3-b1f0-4a38ae898075", "type": "concept", "title": "Volume, mix, revenue, margin, inventory, and capacity alignment"}, {"id": "094f089a-4bf2-47d1-b71c-62222700dc97", "type": "concept", "title": "Decision logs and gap-closing plans"}], "description": "S&OP turns the demand plan into cross-functional executive decisions."}]}, {"id": "38fc905d-d7ac-4bb9-86d2-f74356e0d3d6", "type": "topic", "title": "Inventory, Safety Stock, Service Levels, and Forecast Error", "description": "Translate forecast uncertainty into inventory policies, service-level choices, and working-capital tradeoffs.", "children": [{"id": "e6144bf9-c22d-4188-9964-7c8e97a5ece1", "type": "subtopic", "title": "Forecast Error and Inventory", "children": [{"id": "6d284e37-8bec-447c-a588-2eb4537e86a1", "type": "concept", "title": "Demand variability, lead-time variability, safety stock, reorder point, cycle stock, and buffer strategy"}, {"id": "f3ff48f3-c556-4497-93b1-f0898fbcf421", "type": "concept", "title": "Service level, fill rate, stockout probability, and shortage cost"}, {"id": "2cfa8a01-2fde-490a-97ed-26aa74466bbc", "type": "concept", "title": "Error reduction versus buffer investment"}], "description": "Forecast error becomes real money through safety stock, expedites, stockouts, and obsolescence."}, {"id": "e0180f2a-8963-4859-a042-befe25ee60b6", "type": "subtopic", "title": "Inventory Policy Integration", "children": [{"id": "e8df139c-15ef-47ab-909e-daccbe425cc7", "type": "concept", "title": "EOQ, min-max, periodic review, continuous review, ABC/XYZ classification, and inventory segmentation"}, {"id": "15473666-42ec-41cf-b2bb-423df0965bc1", "type": "concept", "title": "Forecast horizon, lead time, order frequency, and lot size"}, {"id": "0c2878d4-033d-4f08-adbf-a6532de3605e", "type": "concept", "title": "Balancing service, cost, and working capital"}], "description": "Demand forecasts must connect to replenishment and inventory policies."}, {"id": "73ebb44d-890a-4023-badc-4f78e5da94fb", "type": "subtopic", "title": "Bullwhip and Supply Chain Coordination", "children": [{"id": "5dcbc270-6080-4ceb-8b71-a2541ffa545a", "type": "concept", "title": "Bullwhip effect, order batching, price promotions, rationing, lead times, and information distortion"}, {"id": "1730d42c-8998-4cf7-b8fd-d1bf523467df", "type": "concept", "title": "Information sharing, smoothing, collaboration, and postponement"}, {"id": "9f8a7431-f21e-4642-bd53-f8d300aaadff", "type": "concept", "title": "Forecasting as coordination mechanism"}], "description": "Poor forecasting and incentives can amplify demand variation upstream."}]}, {"id": "4c0aa084-1a8b-4d43-b1aa-88baf09fbca7", "type": "topic", "title": "Aggregate Planning, Capacity, MPS, MRP, and ERP Integration", "description": "Link demand plans to production, capacity, master schedules, material requirements, and planning systems.", "children": [{"id": "da22ffe1-4b41-46a6-aacd-5c6b916c6ad8", "type": "subtopic", "title": "Aggregate Planning and Capacity", "children": [{"id": "8a022851-8862-402e-b84d-bb8dac3b7cdc", "type": "concept", "title": "Aggregate planning, level strategy, chase strategy, mixed strategy, workforce planning, and capacity constraints"}, {"id": "dc2b7865-eeb7-431f-baf5-435774eb69f1", "type": "concep